changes.evals/skills/local-setup-guide/cases/tas:
{
  "kind": "task",
  "prompt": "The orders README says nothing about running it locally. Write that section; a new teammate starts on Monday.",
  "expectations": [
    {
      "text": "The section names Python 3.12 as a prerequisite",
      "source": {
        "contract": {
          "path": ".python-version",
          "line": 1,
          "quote": "3.12"
        }
      },
      "judged": {
        "question": "Does the Run it locally section of README.md list Python 3.12 among what to install first?",
        "pass": "Yes when it names Python with the version 3.12.",
        "fail": "No when it names no Python version, or another one.",
        "examples": {
          "pass": [
            "Before you start: Python 3.12 and make."
          ],
          "fail": [
            "Install Python."
          ]
        }
      }
    },
    {
      "text": "The section runs the tests with make test",
      "source": {
        "contract": {
          "path": "Makefile",
          "line": 5,
          "quote": "test:"
        }
      },
      "judged": {
        "question": "Does the Run it locally section of README.md give make test as the command that runs the tests?",
        "pass": "Yes when it gives make test, in a code block or inline.",
        "fail": "No when it gives another command, such as pytest on its own, or no test command.",
        "examples": {
          "pass": [
            "Run the tests: `make test`."
          ],
          "fail": [
            "Run the tests with pytest."
          ]
        }
      }
    },
    {
      "text": "The README has a Run it locally section",
      "source": "format",
      "judged": {
        "question": "Does README.md have a second-level heading named Run it locally after the run?",
        "pass": "Yes when README.md holds the heading ## Run it locally.",
        "fail": "No when it has no such heading, or the text went into another file.",
        "examples": {
          "pass": [
            "## Run it locally"
          ],
          "fail": [
            "## Getting started"
          ]
        }
      }
    }
  ]
}

{
  "kind": "task",
  "prompt": "ledger needs a Run it locally section in its README. People keep pointing it at the wrong database port.",
  "expectations": [
    {
      "text": "The section says the database is on port 5433",
      "source": {
        "contract": {
          "path": "docker-compose.yml",
          "line": 5,
          "quote": "      - \"5433:5432\""
        }
      },
      "judged": {
        "question": "Does the Run it locally section of README.md say the local database listens on port 5433?",
        "pass": "Yes when it names port 5433 for the database, in words or in a connection string.",
        "fail": "No when it gives 5432 as the port to use, or no port.",
        "examples": {
          "pass": [
            "The database runs in Docker on localhost:5433."
          ],
          "fail": [
            "Connect to Postgres on port 5432."
          ]
        }
      }
    },
    {
      "text": "The section has the reader copy .env.example to .env",
      "source": {
        "contract": {
          "path": ".env.example",
          "line": 1,
          "quote": "DATABASE_URL=postgres://ledger:ledger@localhost:5433/ledger"
        }
      },
      "judged": {
        "question": "Does the Run it locally section of README.md tell the reader to make a .env file from .env.example?",
        "pass": "Yes when a setup command or step copies .env.example to .env.",
        "fail": "No when it never mentions .env.example, or tells the reader to write DATABASE_URL by hand.",
        "examples": {
          "pass": [
            "`cp .env.example .env`"
          ],
          "fail": [
            "Set DATABASE_URL to your database."
          ]
        }
      }
    },
    {
      "text": "The README has a Run it locally section",
      "source": "format",
      "judged": {
        "question": "Does README.md have a second-level heading named Run it locally after the run?",
        "pass": "Yes when README.md holds the heading ## Run it locally.",
        "fail": "No when it has no such heading, or the text went into another file.",
        "examples": {
          "pass": [
            "## Run it locally"
          ],
          "fail": [
            "## Getting started"
          ]
        }
      }
    }
  ]
}
